19	pub fn read_bytes(path: &Path, limit: u64) -> Result<Vec<u8>> {
20	    let mut options = fs::OpenOptions::new();
21	    options.read(true);
22	    #[cfg(unix)]
23	    {
24	        use std::os::unix::fs::OpenOptionsExt;
25	        // A path can become a pipe or symlink between authorization and open.
26	        options.custom_flags(libc::O_NONBLOCK | libc::O_NOFOLLOW);
27	    }
28	    let file = options
29	        .open(path)
30	        .map_err(|e| format!("{}: {e}", path.display()))?;
31	    let meta = file.metadata().map_err(|e| e.to_string())?;
32	    if !meta.is_file() || meta.len() > limit {
33	        return Err(format!(
34	            "Not a regular file, or larger than {} MiB",
35	            limit / 1024 / 1024
36	        ));
37	    }
38	    let mut bytes = Vec::new();
39	    file.take(limit + 1)
40	        .read_to_end(&mut bytes)
41	        .map_err(|e| e.to_string())?;
42	    if bytes.len() as u64 > limit {
43	        return Err("File grew beyond the size limit while reading".into());
44	    }
45	    Ok(bytes)
46	}
