59	pub fn snapshot(path: &Path) -> Result<Snapshot> {
60	    let bytes = read_bytes(path, MAX_BYTES)?;
61	    let hash = hash(&bytes);
62	    let text = String::from_utf8(bytes).map_err(|_| "Only UTF-8 documents are supported")?;
63	    Ok(Snapshot { text, hash })
64	}
