95	pub enum SaveResult {
96	    Saved {
97	        snapshot: Snapshot,
98	    },
99	    Conflict {
100	        snapshot: Option<Snapshot>,
101	        error: Option<String>,
102	    },
103	}
104	
105	pub fn save(path: &Path, expected: &str, text: &str) -> Result<SaveResult> {
106	    if text.len() as u64 > MAX_BYTES {
107	        return Err("Document exceeds 16 MiB".into());
108	    }
109	    let disk = match snapshot(path) {
110	        Ok(disk) => disk,
111	        Err(error) => {
112	            return Ok(SaveResult::Conflict {
113	                snapshot: None,
114	                error: Some(error),
115	            })
116	        }
117	    };
118	    if disk.hash != expected {
119	        return Ok(SaveResult::Conflict {
120	            snapshot: Some(disk),
121	            error: None,
122	        });
123	    }
124	    if disk.text == text {
125	        return Ok(SaveResult::Saved { snapshot: disk });
126	    }
127	    atomic_write(path, text, false)?;
128	    // Return the bytes we wrote, not a later external writer's version.
129	    Ok(SaveResult::Saved {
130	        snapshot: text_snapshot(text),
131	    })
132	}
