134	pub fn atomic_write(path: &Path, text: &str, create_only: bool) -> Result<()> {
135	    if text.len() as u64 > MAX_BYTES {
136	        return Err("Document exceeds 16 MiB".into());
137	    }
138	    let parent = path.parent().ok_or("Missing parent directory")?;
139	    let mut tmp = tempfile::NamedTempFile::new_in(parent).map_err(|e| e.to_string())?;
140	    if !create_only {
141	        let permissions = fs::metadata(path).map_err(|e| e.to_string())?.permissions();
142	        tmp.as_file()
143	            .set_permissions(permissions)
144	            .map_err(|e| e.to_string())?;
145	    }
146	    tmp.write_all(text.as_bytes()).map_err(|e| e.to_string())?;
147	    tmp.as_file().sync_all().map_err(|e| e.to_string())?;
148	    if create_only {
149	        tmp.persist_noclobber(path).map_err(|e| e.to_string())?;
150	    } else {
151	        tmp.persist(path).map_err(|e| e.to_string())?;
152	    }
153	    fs::File::open(parent)
154	        .and_then(|f| f.sync_all())
155	        .map_err(|e| e.to_string())?;
156	    Ok(())
157	}
