204	    #[test]
205	    fn directory_watch_observes_chunked_writes_rename_and_recreation() {
206	        use notify_debouncer_full::{new_debouncer, notify::RecursiveMode, DebounceEventResult};
207	        use std::{
208	            sync::mpsc,
209	            time::{Duration, Instant},
210	        };
211	        let dir = tempfile::tempdir().unwrap();
212	        let path = dir.path().join("watched.md");
213	        fs::write(&path, "original").unwrap();
214	        let (send, recv) = mpsc::channel();
215	        let mut watcher = new_debouncer(
216	            Duration::from_millis(100),
217	            None,
218	            move |events: DebounceEventResult| {
219	                if events.is_ok() {
220	                    let _ = send.send(());
221	                }
222	            },
223	        )
224	        .unwrap();
225	        watcher
226	            .watch(dir.path(), RecursiveMode::NonRecursive)
227	            .unwrap();
228	        let observed = |expected: Option<&str>| {
229	            let start = Instant::now();
230	            loop {
231	                recv.recv_timeout(Duration::from_secs(5))
232	                    .expect("directory event");
233	                if snapshot(&path).ok().as_ref().map(|s| s.text.as_str()) == expected {
234	                    break;
235	                }
236	                assert!(start.elapsed() < Duration::from_secs(5));
237	            }
238	        };
239	        let mut file = fs::File::create(&path).unwrap();
240	        file.write_all(b"chunk ").unwrap();
241	        std::thread::sleep(Duration::from_millis(20));
242	        file.write_all(b"complete").unwrap();
243	        drop(file);
244	        observed(Some("chunk complete"));
245	        atomic_write(&path, "replacement", false).unwrap();
246	        observed(Some("replacement"));
247	        fs::remove_file(&path).unwrap();
248	        observed(None);
249	        fs::write(&path, "recreated").unwrap();
250	        observed(Some("recreated"));
251	    }
