25	#[derive(Default)]
26	pub struct Inner {
27	    roots: HashSet<PathBuf>,
28	    grants: HashSet<PathBuf>,
29	    open: HashSet<PathBuf>,
30	    directories: HashSet<PathBuf>,
31	    assets: HashMap<PathBuf, HashSet<PathBuf>>,
32	    watchers: HashMap<PathBuf, Debouncer<RecommendedWatcher, RecommendedCache>>,
33	    requests: VecDeque<Request>,
34	}
35	#[derive(Default)]
36	pub struct Service(pub Mutex<Inner>);
37	
38	impl Inner {
39	    fn allowed(&self, path: &Path) -> Result<PathBuf> {
40	        let p = files::identity(path)?;
41	        if self.grants.contains(&p) || self.roots.iter().any(|r| p.starts_with(r)) {
42	            Ok(p)
43	        } else {
44	            Err("This path has not been authorized. Use Open File or Open Folder.".into())
45	        }
46	    }
47	    fn registered(&self, path: &Path) -> Result<()> {
48	        if self.open.contains(path) {
49	            Ok(())
50	        } else {
51	            Err("Document is not open".into())
52	        }
53	    }
54	    fn validate_session(&self, session: &Session) -> Result<()> {
55	        session.validate()?;
56	        for doc in &session.documents {
57	            self.registered(&doc.path)?;
58	        }
59	        if session
60	            .workspace
61	            .as_ref()
62	            .is_some_and(|p| !self.roots.contains(p) && !self.directories.contains(p))
63	        {
64	            return Err("Recovery workspace has not been authorized".into());
65	        }
66	        Ok(())
67	    }
68	    fn document(&self, path: &Path) -> Result<PathBuf> {
69	        let p = self.allowed(path)?;
70	        if p != path || !self.open.contains(&p) {
71	            return Err("Document is not open, or its path now points elsewhere".into());
72	        }
73	        Ok(p)
74	    }
75	    fn grant(&mut self, request: &Request) {
76	        if request.directory {
77	            self.roots.insert(request.path.clone());
78	        } else {
79	            self.grants.insert(request.path.clone());
80	        }
81	    }
82	    fn watches(&mut self, app: &AppHandle) -> Result<()> {
83	        let mut wanted = self.directories.clone();
84	        wanted.extend(self.assets.values().flat_map(|paths| paths.iter().cloned()));
85	        wanted.extend(
86	            self.open
87	                .iter()
88	                .filter_map(|p| p.parent().map(Path::to_path_buf)),
89	        );
90	        self.watchers.retain(|p, _| wanted.contains(p));
91	        for path in wanted {
92	            if self.watchers.contains_key(&path)
93	                || !path.is_dir()
94	                || !files::canonical(&path).is_ok_and(|p| p == path)
95	            {
96	                continue;
97	            }
98	            let handle = app.clone();
99	            let mut watcher = new_debouncer(
100	                Duration::from_millis(350),
101	                None,
102	                move |event: DebounceEventResult| match event {
103	                    Ok(_) => {
104	                        let _ = handle.emit("disk-changed", ());
105	                    }
106	                    Err(errors) => {
107	                        let _ = handle.emit("service-error", format!("File watcher: {errors:?}"));
108	                    }
109	                },
110	            )
111	            .map_err(|e| e.to_string())?;
112	            watcher
113	                .watch(&path, RecursiveMode::NonRecursive)
114	                .map_err(|e| e.to_string())?;
115	            self.watchers.insert(path, watcher);
116	        }
117	        Ok(())
118	    }
119	}
