121	pub fn enqueue(app: &AppHandle, request: Request) {
122	    let service = app.state::<Service>();
123	    let mut inner = service.0.lock().unwrap();
124	    inner.grant(&request);
125	    inner.requests.push_back(request);
126	    drop(inner);
127	    let _ = app.emit("open-requests", ());
128	    if let Some(window) = app.get_webview_window("main") {
129	        let _ = window.show();
130	        let _ = window.unminimize();
131	        let _ = window.set_focus();
132	    }
133	}
