231	#[tauri::command]
232	pub async fn list_directory(
233	    app: AppHandle,
234	    state: State<'_, Service>,
235	    path: PathBuf,
236	) -> Result<Vec<Entry>> {
237	    let mut inner = state.0.lock().unwrap();
238	    let path = inner.allowed(&path)?;
239	    let mut entries = Vec::new();
240	    for entry in fs::read_dir(&path).map_err(|e| e.to_string())? {
241	        let entry = entry.map_err(|e| e.to_string())?;
242	        let name = entry.file_name().to_string_lossy().into_owned();
243	        if search::EXCLUDED.contains(&name.as_str()) {
244	            continue;
245	        }
246	        // Do not traverse symlinks; they may leave the authorized workspace.
247	        let kind = entry.file_type().map_err(|e| e.to_string())?;
248	        if kind.is_dir() || (kind.is_file() && files::supported_document(&entry.path())) {
249	            entries.push(Entry {
250	                path: entry.path(),
251	                name,
252	                directory: kind.is_dir(),
253	            });
254	        }
255	    }
256	    entries.sort_by(|a, b| {
257	        b.directory
258	            .cmp(&a.directory)
259	            .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
260	    });
261	    inner.directories.insert(path);
262	    inner.watches(&app)?;
263	    Ok(entries)
264	}
