407	pub async fn preview_asset(
408	    app: AppHandle,
409	    state: State<'_, Service>,
410	    document: PathBuf,
411	    reference: String,
412	) -> Result<PreviewAsset> {
413	    let mut inner = state.0.lock().unwrap();
414	    let target = local_asset(&inner, &document, &reference)?;
415	    let paths = inner.assets.entry(document.clone()).or_default();
416	    let parent = target.parent().ok_or("Missing asset parent")?.to_path_buf();
417	    if paths.len() >= 128 && !paths.contains(&parent) {
418	        return Err("Preview asset directory limit reached".into());
419	    }
420	    paths.insert(parent);
421	    inner.watches(&app)?;
422	    let ext = target
423	        .extension()
424	        .unwrap_or_default()
425	        .to_string_lossy()
426	        .to_ascii_lowercase();
427	    if matches!(ext.as_str(), "css" | "js" | "mjs") {
428	        drop(inner);
429	        let bytes = files::read_bytes(&target, files::MAX_BYTES)?;
430	        return Ok(PreviewAsset {
431	            kind: if ext == "css" { "style" } else { "script" },
432	            value: String::from_utf8(bytes).map_err(|_| "Preview asset is not UTF-8")?,
433	            path: target,
434	            mime: Some(if ext == "css" {
435	                "text/css"
436	            } else {
437	                "text/javascript"
438	            }),
439	        });
440	    }
441	    let mime = match ext.as_str() {
442	        "png" => "image/png",
443	        "jpg" | "jpeg" => "image/jpeg",
444	        "gif" => "image/gif",
445	        "webp" => "image/webp",
446	        "svg" => "image/svg+xml",
447	        "woff" => "font/woff",
448	        "woff2" => "font/woff2",
449	        "ttf" => "font/ttf",
450	        _ => {
451	            return Err(
452	                "Unsupported preview asset; use a development server for this resource type".into(),
453	            )
454	        }
455	    };
456	    drop(inner);
457	    let bytes = files::read_bytes(&target, files::MAX_BYTES)?;
458	    Ok(PreviewAsset {
459	        kind: "data",
460	        path: target,
461	        value: format!(
462	            "data:{mime};base64,{}",
463	            base64::engine::general_purpose::STANDARD.encode(bytes)
464	        ),
465	        mime: Some(mime),
466	    })
467	}
