81	fn private_owned(path: &Path, directory: bool) -> bool {
82	    #[cfg(unix)]
83	    {
84	        use std::os::unix::fs::MetadataExt;
85	        fs::symlink_metadata(path).is_ok_and(|m| {
86	            !m.file_type().is_symlink()
87	                && (!directory || m.is_dir())
88	                && m.uid() == unsafe { libc::geteuid() }
89	                && m.mode() & 0o077 == 0
90	        })
91	    }
92	    #[cfg(not(unix))]
93	    {
94	        let _ = (path, directory);
95	        false
96	    }
97	}
