116	fn read_registration(path: &Path) -> Option<Registration> {
117	    if !private_owned(path, false) {
118	        return None;
119	    }
120	    let bytes = crate::files::read_bytes(path, MAX_REGISTRY_BYTES).ok()?;
121	    let registration: Registration = serde_json::from_slice(&bytes).ok()?;
122	    if !safe_id(&registration.id)
123	        || registration.project_root.is_empty()
124	        || registration.socket_path.is_empty()
125	    {
126	        return None;
127	    }
128	    Some(registration)
129	}
