131	fn registrations() -> Vec<Registration> {
132	    if !private_owned(&registry_dir(), true) {
133	        return Vec::new();
134	    }
135	    let Ok(entries) = fs::read_dir(registry_dir()) else {
136	        return Vec::new();
137	    };
138	    entries
139	        .filter_map(|entry| entry.ok())
140	        .filter(|entry| entry.path().extension().is_some_and(|ext| ext == "json"))
141	        .filter_map(|entry| read_registration(&entry.path()))
142	        .filter(|registration| {
143	            let socket = Path::new(&registration.socket_path);
144	            #[cfg(unix)]
145	            {
146	                use std::os::unix::fs::FileTypeExt;
147	                socket.parent() == Some(registry_dir().as_path())
148	                    && private_owned(socket, false)
149	                    && fs::symlink_metadata(socket).is_ok_and(|m| m.file_type().is_socket())
150	                    && registration.pid > 0
151	                    && unsafe { libc::kill(registration.pid as i32, 0) == 0 }
152	            }
153	            #[cfg(not(unix))]
154	            {
155	                let _ = socket;
156	                false
157	            }
158	        })
159	        .collect()
160	}
