169	            project_root: registration.project_root,
170	            session_id: registration.session_id,
171	            block_id: registration.block_id,
172	            process: registration.process,
173	            busy: registration.busy.unwrap_or(false),
174	            connected: true,
175	        })
176	        .collect()
177	}
