312	pub(crate) fn discover_targets(project_root: Option<String>) -> Vec<AgentTarget> {
313	    let project = project_root.as_deref();
314	    let mut targets = registered_targets(project);
315	    let registered_pairs: Vec<(String, String)> = targets
316	        .iter()
317	        .filter_map(|target| Some((target.session_id.clone()?, target.block_id.clone()?)))
318	        .collect();
319	    targets.extend(rex_targets(project).into_iter().filter(|target| {
320	        !registered_pairs.iter().any(|(session, block)| {
321	            target.session_id.as_deref() == Some(session.as_str())
322	                && target.block_id.as_deref() == Some(block.as_str())
323	        })
324	    }));
325	    targets.sort_by_key(|target| (!target.connected, target.busy, target.label.clone()));
326	    targets
327	}
