340	pub(crate) fn validate_note(message: &FeedbackMessage, draft: bool) -> Result<(), String> {
341	    if message
342	        .intent
343	        .as_deref()
344	        .is_some_and(|value| !matches!(value, "explain" | "review" | "edit"))
345	    {
346	        return Err("Unknown feedback intent".into());
347	    }
348	    if message.source != "sidelit" || !safe_id(&message.id) {
349	        return Err("Invalid Sidelit feedback message".into());
350	    }
351	    if (!draft && message.instruction.trim().is_empty()) || message.instruction.len() > 8000 {
352	        return Err("Feedback instruction must be between 1 and 8000 bytes".into());
353	    }
354	    if serde_json::to_vec(&message.document).map_or(true, |bytes| bytes.len() > 6000)
355	        || serde_json::to_vec(&message.selection)
356	            .map_or(true, |bytes| bytes.len() > if draft { 16000 } else { 8000 })
357	    {
358	        return Err("Feedback context is too large".into());
359	    }
360	    if !matches!(
361	        message.document.get("format").and_then(Value::as_str),
362	        Some("markdown" | "html" | "mdx" | "url")
363	    ) || !matches!(
364	        message.selection.get("type").and_then(Value::as_str),
365	        Some("text" | "element" | "document")
366	    ) || !message.selection.get("text").is_some_and(Value::is_string)
367	    {
368	        return Err("Invalid feedback context".into());
369	    }
370	    if !message.document.get("path").is_some_and(Value::is_string)
371	        && !message.document.get("url").is_some_and(Value::is_string)
372	    {
373	        return Err("Feedback needs a document path or URL".into());
374	    }
375	    if let Some(url) = message.document.get("url") {
376	        let valid = url
377	            .as_str()
378	            .and_then(|value| url::Url::parse(value).ok())
379	            .is_some_and(|url| matches!(url.scheme(), "http" | "https"));
380	        if !valid {
381	            return Err("Invalid feedback page URL".into());
382	        }
383	    }
384	    let strings = |value: &Value, keys: &[&str]| {
385	        keys.iter()
386	            .all(|key| value.get(key).is_none_or(Value::is_string))
387	    };
388	    if !strings(&message.document, &["path", "diskHash", "capturedAt"])
389	        || !strings(
390	            &message.selection,
391	            &[
392	                "selector",
393	                "tag",
394	                "id",
395	                "surrounding",
396	                "prefix",
397	                "suffix",
398	                "anchorText",
399	                "locatorConfidence",
400	            ],
401	        )
402	        || message
403	            .document
404	            .get("revision")
405	            .is_some_and(|v| v.as_u64().is_none_or(|n| n > 9_007_199_254_740_991))
406	        || message
407	            .document
408	            .get("unsaved")
409	            .is_some_and(|v| !v.is_boolean())
410	        || message
411	            .selection
412	            .get("truncated")
413	            .is_some_and(|v| !v.is_boolean())
414	        || message.selection.get("sourceLine").is_some_and(|v| {
415	            !v.is_null()
416	                && v.as_u64()
417	                    .is_none_or(|n| n == 0 || n > 9_007_199_254_740_991)
418	        })
419	        || message.selection.get("classes").is_some_and(|v| {
420	            v.as_array()
421	                .is_none_or(|items| items.len() > 8 || items.iter().any(|v| !v.is_string()))
422	        })
423	        || message.selection.get("styles").is_some_and(|v| {
424	            v.as_object()
425	                .is_none_or(|styles| styles.values().any(|v| !v.is_string()))
426	        })
427	    {
428	        return Err("Invalid feedback capture metadata".into());
429	    }
430	    Ok(())
431	}
