433	fn note_scope(note: &FeedbackMessage) -> Option<String> {
434	    if let Some(root) = note.project_root.as_deref().filter(|root| !root.is_empty()) {
435	        return Path::new(root)
436	            .is_absolute()
437	            .then(|| format!("project:{root}"));
438	    }
439	    let url = url::Url::parse(note.document.get("url")?.as_str()?).ok()?;
440	    matches!(url.scheme(), "http" | "https")
441	        .then(|| format!("page:{}", url.origin().ascii_serialization()))
442	}
