472	pub(crate) fn bridge_health(target_id: &str) -> Result<Value, String> {
473	    let registration = registrations()
474	        .into_iter()
475	        .find(|r| r.id == target_id)
476	        .ok_or("Pi session disconnected")?;
477	    #[cfg(unix)]
478	    {
479	        let mut stream = std::os::unix::net::UnixStream::connect(&registration.socket_path)
480	            .map_err(|e| e.to_string())?;
481	        stream
482	            .set_read_timeout(Some(Duration::from_millis(800)))
483	            .map_err(|e| e.to_string())?;
484	        stream
485	            .set_write_timeout(Some(Duration::from_millis(800)))
486	            .map_err(|e| e.to_string())?;
487	        stream
488	            .write_all(b"{\"op\":\"ping\",\"id\":\"sidelit-doctor\"}\n")
489	            .map_err(|e| e.to_string())?;
490	        let mut line = String::new();
491	        BufReader::new(stream.take(8193))
492	            .read_line(&mut line)
493	            .map_err(|e| e.to_string())?;
494	        let response: Value = serde_json::from_str(&line).map_err(|e| e.to_string())?;
495	        if line.len() > 8192
496	            || response["id"] != "sidelit-doctor"
497	            || response["status"] != "ready"
498	            || response["protocol"] != 1
499	        {
500	            return Err("Bridge needs an update or /reload in Pi".into());
501	        }
502	        Ok(response)
503	    }
504	    #[cfg(not(unix))]
505	    {
506	        let _ = registration;
507	        Err("Pi requires a Unix-like desktop".into())
508	    }
509	}
