545	fn delivery(target_id: String, message: Value, id: &str) -> Result<DeliveryAck, String> {
546	    let registration = registrations()
547	        .into_iter()
548	        .find(|registration| registration.id == target_id)
549	        .ok_or_else(|| "That Pi session is no longer connected".to_string())?;
550	    if message.get("op").and_then(Value::as_str) != Some("status") {
551	        let project = if message.get("notes").is_some() {
552	            let batch: FeedbackBatch = serde_json::from_value(message.clone())
553	                .map_err(|e| format!("Invalid review batch: {e}"))?;
554	            validate_batch(&batch)?;
555	            batch.project_root
556	        } else {
557	            let feedback: FeedbackMessage = serde_json::from_value(message.clone())
558	                .map_err(|e| format!("Invalid feedback: {e}"))?;
559	            validate_note(&feedback, false)?;
560	            feedback.project_root
561	        };
562	        if !compatible(project.as_deref(), &registration.project_root) {
563	            return Err("The selected Pi session belongs to a different project".into());
564	        }
565	    }
566	    #[cfg(not(unix))]
567	    return Err("Pi delivery currently requires a Unix-like desktop".into());
568	    #[cfg(unix)]
569	    {
570	        let socket = Path::new(&registration.socket_path);
571	        if !private_owned(socket, false) {
572	            return Err("Unsafe Pi bridge socket permissions".into());
573	        }
574	        let mut stream = std::os::unix::net::UnixStream::connect(socket)
575	            .map_err(|e| format!("Could not reach Pi: {e}"))?;
576	        stream
577	            .set_read_timeout(Some(Duration::from_secs(2)))
578	            .map_err(|e| e.to_string())?;
579	        stream
580	            .set_write_timeout(Some(Duration::from_secs(2)))
581	            .map_err(|e| e.to_string())?;
582	        let line = serde_json::to_string(&message).map_err(|e| e.to_string())?;
583	        stream
584	            .write_all(line.as_bytes())
585	            .and_then(|_| stream.write_all(b"\n"))
586	            .map_err(|e| format!("Could not send feedback to Pi: {e}"))?;
587	        let mut response = String::new();
588	        BufReader::new(stream.take(8193))
589	            .read_line(&mut response)
590	            .map_err(|e| format!("Pi did not acknowledge feedback: {e}"))?;
591	        parse_ack(&response, id)
592	    }
593	}
594	
595	fn parse_ack(response: &str, id: &str) -> Result<DeliveryAck, String> {
596	    if response.len() > 8192 || !response.ends_with('\n') {
597	        return Err("Pi acknowledgment was incomplete or too large".into());
598	    }
599	    let value: Value =
600	        serde_json::from_str(response).map_err(|e| format!("Invalid Pi acknowledgment: {e}"))?;
601	    if value.get("id").and_then(Value::as_str) != Some(id) {
602	        return Err("Pi acknowledged a different message".into());
603	    }
604	    if value.get("status").and_then(Value::as_str) == Some("error") {
605	        return Err(value
606	            .get("error")
607	            .and_then(Value::as_str)
608	            .unwrap_or("Pi rejected feedback")
609	            .to_string());
610	    }
611	    let ack: DeliveryAck = serde_json::from_value(value).map_err(|e| e.to_string())?;
612	    if !matches!(ack.status.as_str(), "received" | "accepted" | "duplicate")
613	        || !matches!(ack.delivery.as_str(), "submitted" | "queued" | "consumed")
614	    {
615	        return Err("Unknown Pi acknowledgment status".into());
616	    }
617	    Ok(ack)
618	}
