263	      changing.current = false;
264	      applied.current = text;
265	      root.current!.scrollTop = scroll;
266	    }
267	  }, [text]);
268	  return (
269	    <div
270	      className={'rich-editor' + (!editable ? ' reading' : '')}
271	      ref={root}
272	      onMouseUp={captureText}
273	      onKeyUp={event => { if (event.shiftKey && event.key.startsWith('Arrow')) captureText(); }}
274	      onPointerDownCapture={event => { if (inspection.current) event.preventDefault(); }}
275	      onMouseMove={(event) => {
276	        const target = (event.target as Element).closest?.(".ProseMirror > *, .ProseMirror > * *");
277	        if (!inspection.current || !target || !root.current?.contains(target)) {
278	          root.current?.querySelectorAll("[data-sidelit-inspect-hover]").forEach((node) => node.removeAttribute("data-sidelit-inspect-hover"));
279	          return;
280	        }
281	        root.current?.querySelectorAll("[data-sidelit-inspect-hover]").forEach((node) => {
282	          if (node !== target) node.removeAttribute("data-sidelit-inspect-hover");
283	        });
284	        target.setAttribute("data-sidelit-inspect-hover", "true");
285	      }}
286	      onMouseLeave={() => root.current?.querySelectorAll("[data-sidelit-inspect-hover]").forEach((node) => node.removeAttribute("data-sidelit-inspect-hover"))}
287	      onClickCapture={(event) => {
288	        if (inspection.current) {
289	          const target = (event.target as Element).closest?.(".ProseMirror > *, .ProseMirror > * *");
290	          if (target && root.current?.contains(target)) {
291	            event.preventDefault();
292	            event.stopPropagation();
293	            elementInspection.current?.(elementContext(target, current.current));
294	          }
295	          return;
296	        }
297	        const link = (event.target as Element).closest("a");
298	        if (!link) return;
299	        event.preventDefault();
300	        event.stopPropagation();
301	        void api
302	          .link(path, link.getAttribute("href") ?? "")
303	          .catch(errors.current);
304	      }}
305	    />
306	  );
