1	use crate::files::{canonical, supported_document, Result};
2	use serde::Serialize;
3	use std::path::{Path, PathBuf};
4	
5	#[derive(Clone, Debug, Serialize)]
6	#[serde(rename_all = "camelCase")]
7	pub struct Request {
8	    pub path: PathBuf,
9	    pub directory: bool,
10	    pub source: bool,
11	}
12	
13	pub fn parse(args: &[String], cwd: &Path) -> Result<Option<Request>> {
14	    let mut source = false;
15	    let mut path = None;
16	    let mut literal = false;
17	    for arg in args {
18	        if !literal && arg == "--" {
19	            literal = true;
20	            continue;
21	        }
22	        if !literal && arg == "--source" {
23	            source = true;
24	            continue;
25	        }
26	        if !literal && arg.starts_with('-') {
27	            return Err(format!("Unknown option: {arg}. Use --help."));
28	        }
29	        if path.is_some() {
30	            return Err("Open one file or directory per CLI request".into());
31	        }
32	        path = Some(cwd.join(arg));
33	    }
34	    path.map(|p| {
35	        let path = canonical(&p)?;
36	        let directory = path.is_dir();
37	        if !directory && !supported_document(&path) {
38	            return Err("Choose a .md, .markdown, .mdx, .html, or .htm file".into());
39	        }
40	        if directory && source {
41	            return Err("--source requires a supported document file".into());
42	        }
43	        Ok(Request {
44	            path,
45	            directory,
46	            source,
47	        })
48	    })
49	    .transpose()
50	}
51	
