2	import { createHash } from 'node:crypto';
3	import { chmod, lstat, mkdir, realpath, rename, unlink, writeFile } from 'node:fs/promises';
4	import { basename, join } from 'node:path';
5	import { StringDecoder } from 'node:string_decoder';
6	import type { ExtensionAPI, ExtensionContext } from '@earendil-works/pi-coding-agent';
7	import { validFeedback, promptFor, type Feedback } from './protocol';
8	
9	export type Receipt = { id: string; status: 'received' | 'accepted' | 'duplicate'; delivery: 'submitted' | 'queued' | 'consumed' };
10	type Record = { digest: string; receipt: Receipt; sentAt?: number };
11	export const registryDirectory = () => `/tmp/sidelit-pi-${process.getuid?.()}`;
12	// Long enough for Pi's pre-run checks; a request cannot be called lost while they run.
13	export const NOT_STARTED_AFTER_MS = 10_000;
14	
15	export default function sidelit(pi: ExtensionAPI) {
16	  let server: ReturnType<typeof createServer> | undefined;
17	  let registration: { id: string; socketPath: string; projectRoot: string; sessionId?: string; blockId?: string; label: string; process: string; busy: boolean; pid: number; piSessionId: string } | undefined;
18	  let context: ExtensionContext;
19	  let seen = new Map<string, Record>();
20	  const sockets = new Set<Socket>();
21	  let writes = Promise.resolve();
22	  const publish = (busy: boolean) => {
23	    if (!registration) return writes;
24	    registration.busy = busy;
25	    const file = registration.socketPath + '.json', json = JSON.stringify(registration);
26	    writes = writes.then(async () => {
27	      await writeFile(file + '.tmp', json, { mode: 0o600 });
28	      await rename(file + '.tmp', file);
29	    });
30	    return writes;
31	  };
32	  const stop = async () => {
33	    const current = registration; registration = undefined;
34	    for (const socket of sockets) socket.destroy();
35	    if (server) { const closing = server; server = undefined; await new Promise<void>(resolve => closing.close(() => resolve())); }
36	    await writes.catch(() => {}); writes = Promise.resolve();
