43	  };
44	  // sendUserMessage returns nothing and Pi swallows rejections such as missing auth.
45	  // Unconsumed, with Pi idle and nothing queued, means the request will never run.
46	  const notStarted = (record: Record) => record.receipt.status === 'received' && context.isIdle() && !context.hasPendingMessages()
