48	  const deliver = (message: Feedback, digest: string) => {
49	    const receipt: Receipt = { id: message.id, status: 'received', delivery: context.isIdle() ? 'submitted' : 'queued' };
50	    // Record only after sending, so a synchronous failure leaves the ID free to retry.
51	    // The API is void: only message_start below proves Pi consumed the instruction.
