60	      const record = seen.get(String((value as { id?: string }).id));
61	      if (!record) throw new Error('No receipt for that message in this Pi session');
62	      return notStarted(record) ? { id: record.receipt.id, status: 'failed', delivery: 'none' } : record.receipt;
63	    }
64	    if (!validFeedback(value, registration.projectRoot)) throw new Error('Invalid feedback or different project');
65	    const message: Feedback = value;
66	    const digest = createHash('sha256').update(JSON.stringify(message)).digest('hex');
67	    const previous = seen.get(message.id);
68	    if (previous) {
