80	    await mkdir(directory, { recursive: true, mode: 0o700 });
81	    const metadata = await lstat(directory);
82	    if (!metadata.isDirectory() || metadata.isSymbolicLink() || metadata.uid !== process.getuid() || (metadata.mode & 0o077)) throw new Error('Unsafe Sidelit registry directory');
83	    const session = ctx.sessionManager.getSessionId();
84	    const id = createHash('sha256').update(`${process.pid}:${session}`).digest('hex').slice(0, 32);
85	    registration = { id, socketPath: join(directory, id + '.sock'), projectRoot: await realpath(ctx.cwd), sessionId: process.env.REX_SESSION, blockId: process.env.REX_BLOCK, label: `Pi · ${basename(ctx.cwd)} · ${session.slice(0, 8)}`, process: 'pi', pid: process.pid, piSessionId: session, busy: !ctx.isIdle() };
86	    for (const entry of ctx.sessionManager.getEntries()) {
87	      if (entry.type === 'custom' && entry.customType === 'sidelit_feedback_receipt') {
88	        const data = entry.data as { id?: string; digest?: string; receipt?: Receipt; sentAt?: number };
89	        if (data?.id && data.digest && data.receipt) seen.set(data.id, { digest: data.digest, receipt: data.receipt, sentAt: data.sentAt });
90	      }
