4	export const MAX_REVIEW_NOTES = 20;
5	export const MAX_BATCH_BYTES = 30 * 1024;
6	export const intentInstruction = (intent: FeedbackMessage['intent']) => intent === 'explain'
7	  ? 'Explain the selected material. Answer in Pi without editing files.'
8	  : intent === 'review' ? 'Review the selected material. Report findings and suggestions in Pi without editing files.'
9	  : 'Make the requested edit. Re-read the current source before changing it and keep the change scoped to this request.';
10	export const NOT_STARTED = 'Pi did not start this request. Check its model and login in Pi, then retry. The message stays the same.';
11	export interface FeedbackBatch { id: string; source: 'sidelit'; projectRoot?: string; notes: FeedbackMessage[] }
12	export interface ReviewRecord {
13	  version: 1;
14	  notes: FeedbackMessage[];
15	  attempt?: { target: string; message: FeedbackBatch; ack?: DeliveryAck };
16	}
17	export const emptyReview = (): ReviewRecord => ({ version: 1, notes: [] });
18	export function reviewScope(note: FeedbackMessage) {
19	  return note.projectRoot ? 'project:' + note.projectRoot : note.document.url ? 'page:' + new URL(note.document.url).origin : '';
20	}
21	export function batchMessage(notes: FeedbackMessage[], id: string): FeedbackBatch {
22	  if (!notes.length || notes.length > MAX_REVIEW_NOTES) throw Error('Select 1–20 notes.');
23	  if (new Set([id, ...notes.map(note => note.id)]).size !== notes.length + 1) throw Error('Review notes need unique IDs.');
24	  const scope = reviewScope(notes[0]);
25	  if (!scope || notes.some(note => reviewScope(note) !== scope)) throw Error('Select notes from one project or live-page origin. Send other projects separately.');
