76	      if (this.locked(note.id)) throw Error('A delivery attempt cannot be edited.');
77	      const { record } = this.state, exists = record.notes.some(item => item.id === note.id);
78	      if (!exists && record.notes.length >= MAX_REVIEW_NOTES) throw Error('The review list is full (20 notes). Remove notes before adding more.');
79	      if (new TextEncoder().encode(note.instruction).length > 7400) throw Error('The instruction is too long. Shorten it before saving.');
80	      await this.commit({ ...record, notes: exists ? record.notes.map(item => item.id === note.id ? structuredClone(note) : item) : [...record.notes, structuredClone(note)] });
81	    });
82	  }
83	  remove(id: string) {
84	    return this.run(async () => {
85	      if (this.locked(id)) throw Error('Remove the delivery record to remove its notes.');
