87	    });
88	  }
89	  send(target: string, message: FeedbackBatch, approve: () => boolean) {
90	    return this.run(async () => {
91	      if (!approve()) throw Error('The document changed. Review the captured version before sending.');
92	      if (!this.state.record.attempt) {
93	        const current = this.state.record.notes.filter(note => message.notes.some(sent => sent.id === note.id));
94	        if (JSON.stringify(batchMessage(current, message.id)) !== JSON.stringify(message)) throw Error('The notes changed. Review the payload again.');
95	        if (!target) throw Error('Choose a Pi session.');
96	        this.update({ record: { ...this.state.record, attempt: { target, message: structuredClone(message) } } });
97	      }
98	      const attempt = this.state.record.attempt!;
99	      if (attempt.ack) return;
100	      // Keep failed writes frozen too; retries must persist the same attempt before sending.
101	      await this.commit(this.state.record);
102	      if (!approve()) throw Error('The document changed. Review the captured version before retrying.');
103	      const ack = await this.io.sendReview(attempt.target, attempt.message);
104	      if (ack.id !== attempt.message.id) throw Error('Pi acknowledged a different batch.');
105	      await this.commit({ ...this.state.record, attempt: { ...attempt, ack } });
106	    });
107	  }
108	  checkStatus() {
109	    return this.run(async () => {
110	      const { attempt } = this.state.record;
111	      if (!attempt) return;
112	      const ack = await this.io.feedbackStatus(attempt.target, attempt.message.id);
113	      if (ack.id !== attempt.message.id) throw Error('Pi acknowledged a different batch.');
114	      if (ack.status === 'failed') {
115	        // Keep the frozen target and payload; dropping the receipt re-enables retry.
116	        await this.commit({ ...this.state.record, attempt: { target: attempt.target, message: attempt.message } });
117	        throw Error(NOT_STARTED);
118	      }
119	      if (attempt.ack?.status === ack.status && attempt.ack?.delivery === ack.delivery) return;
120	      await this.commit({ ...this.state.record, attempt: { ...attempt, ack } });
121	    });
122	  }
123	  clearAttempt() {
124	    return this.run(async () => {
125	      const { record } = this.state;
126	      const sent = new Set(record.attempt?.message.notes.map(note => note.id));
127	      await this.commit({ version: 1, notes: record.notes.filter(note => !sent.has(note.id)) });
128	    });
129	  }
130	  async clear() {
131	    if (this.state.busy) throw Error('Wait for review notes to finish saving.');
132	    this.update({ busy: true, error: '' });
133	    try { await this.commit(emptyReview()); this.update({ ready: true }); }
134	    catch (error) { this.update({ error: String(error) }); throw error; }
135	    finally { this.update({ busy: false }); }
136	  }
137	}
