51	    for (const rect of Array.from(target.getClientRects()).slice(0, 100)) {
52	      const left = Math.max(rect.left, clip.left), top = Math.max(rect.top, clip.top);
53	      const right = Math.min(rect.right, clip.right), bottom = Math.min(rect.bottom, clip.bottom);
54	      if (right <= left || bottom <= top) continue;
55	      const part = document.createElement('i');
56	      Object.assign(part.style, { left: left + 'px', top: top + 'px', width: right - left + 'px', height: bottom - top + 'px' });
