export default function ChangesBar({ changes, index, source, unmapped, canUndo, onGo, onRevert, onUndo, onCompare, onDone }: {
  changes: Change[]; index: number; source: "disk" | "commit" | undefined; unmapped: boolean; canUndo: boolean;
  onGo: (index: number) => void; onRevert: () => void; onUndo: () => void; onCompare: () => void; onDone: () => void;
